{
  "title": "祠堂的秘密",
  "scene": "你来到了一座古老的祠堂前，大门紧闭，门上的铜锁已生锈。祠堂两旁的石狮子似乎在低语，后方的古树遮天蔽日，使这里更加幽暗。你注意到门边有一块看似新近的石碑，上面刻着模糊的字迹。传说这里的铜锁自祖宗留下后从未开启，但今晚，你却听到了锁内有轻微的声音。",
  "goal": "找到打开祠堂大门的方法",
  "clue": "门边的石碑上刻着模糊的字迹，暗示需要找到祠堂内祖先的遗物，而非直接尝试开锁。",
  "choices": [
    {
      "id": "A",
      "text": "用力敲打铜锁",
      "outcome": "你用力敲打铜锁，锁内的声音突然停止，似乎惊动了什么。门内传来一阵怒吼，显然有人或什么东西被你激怒了。你感到一阵寒意，但大门依然紧闭。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "仔细阅读石碑上的字迹",
      "outcome": "你仔细阅读石碑上的字迹，虽然模糊，但依稀可辨认出一些关键信息。石碑上提到祠堂内有一件祖先的遗物，可以用来打开大门。你决定进入祠堂寻找这件遗物。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "绕到祠堂后寻找其他入口",
      "outcome": "你绕到祠堂后方，发现了一扇小门，但小门也被锁住了。你回到前门，却发现大门上的铜锁变得更加牢固，似乎有什么力量在阻止你。你感到有些沮丧，但还是决定尝试其他方法。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
